1	// RULES.md §"Two encoders, one contract": presence geohashes are written by the
2	// Flutter client (app/lib/geo/geohash.dart, hand-rolled) and read back by the
3	// Cloud Function's geohash range queries (geofire-common). The two only meet if
4	// they encode at the SAME precision — a 9-char client hash never falls inside the
5	// bounds of a 10-char server query, so a precision changed on one side alone
6	// makes sendMessage find nobody, silently, with every test still green.
7	//
8	// The precision is a literal at the call sites, so it is a static signature and
9	// converts to a check; that the two ENCODERS agree character-for-character is not
10	// static and stays prose plus the known-vector suites both tiers commit.
11	//
12	// Dependency-free by design (a local pack's checks must load without the shared
13	// mount): it builds plain finding objects instead of importing the engine helper.
14	
15	// `geohash.encode(p.lat, p.lng, precision: 9)` in the Flutter client.
16	const DART_CALL = /\bencode\s*\(([^)]*)precision:\s*(\d+)\s*\)/g;
17	// `geohashForLocation([lat, lng], 9)` in the Cloud Functions source.
18	const TS_CALL = /\bgeohashForLocation\s*\(\s*\[[^\]]*\]\s*,\s*(\d+)\s*\)/g;
19	
20	const DART_ROOT = 'app/lib/';
21	const TS_ROOT = 'firebase/functions/src/';
22	
23	const rule = {
24	  id: 'shouts-and-whispers/geohash-precision-parity',
25	  severity: 'blocking',
26	  description: 'The client heartbeat and the Cloud Functions encode presence geohashes at the same precision',
27	  doc: '.claudinite/local/packs/shouts-and-whispers/RULES.md',
28	  why: 'the server queries presence by geohash range, so a precision that differs from the one the client wrote makes every range query miss its recipients — no error, no failing test, just messages delivered to nobody',
29	
30	  run(ctx) {
31	    const out = [];
32	    const say = (file, line, what, fix) => out.push({
33	      rule: rule.id, severity: rule.severity, file, line,
34	      what, why: rule.why, fix, doc: rule.doc,
35	    });
36	
37	    const client = sites(ctx, (f) => f.startsWith(DART_ROOT) && f.endsWith('.dart'), DART_CALL, 2);
38	    const server = sites(ctx, (f) => f.startsWith(TS_ROOT) && f.endsWith('.ts'), TS_CALL, 1);
39	
40	    // Staleness guard, the idiom app/test/import_boundary_test.dart already uses:
41	    // if either side's call site has moved out of the scanned tree the guard is
42	    // no longer guarding anything, and that must be loud.
43	    if (!client.length || !server.length) {
44	      say(
45	        !client.length ? `${DART_ROOT}geo/geohash.dart` : `${TS_ROOT}index.ts`,
46	        null,
47	        `no explicit geohash precision found under ${!client.length ? DART_ROOT : TS_ROOT} — the parity guard has nothing to compare`,
48	        'keep the precision an explicit literal at the encode call site (never an implicit library default), or point the guard at its new home',
49	      );
50	      return out;
51	    }
52	
53	    const values = [...new Set([...client, ...server].map((s) => s.precision))];
54	    if (values.length > 1) {
55	      const where = [...client, ...server]
56	        .map((s) => `${s.file}:${s.line} → ${s.precision}`)
57	        .join(', ');
58	      for (const site of server) {
59	        say(
60	          site.file, site.line,
61	          `presence geohash precision disagrees across the tiers (${where})`,
62	          'encode at one precision on both sides (DESIGN.md §3 fixes it at 9), and extend the known-vector tests on both tiers to the new precision',
63	        );
64	      }
65	    }
66	
67	    return out;
68	  },
69	};
70	
71	function sites(ctx, matches, pattern, group) {
72	  const found = [];
73	  for (const file of ctx.files.filter(matches)) {
74	    const text = ctx.read(file);
75	    if (text === null) continue;
76	    pattern.lastIndex = 0;
77	    let m;
78	    while ((m = pattern.exec(text)) !== null) {
79	      found.push({
80	        file,
81	        line: text.slice(0, m.index).split('\n').length,
82	        precision: Number(m[group]),
83	      });
84	    }
85	  }
86	  return found;
87	}
88	
89	export default rule;
